    // one carol
    r = await read('admin_card', { id: A.id }); eq(r.id, A.id); eq(r.card_name, 'alice-one'); eq(r.url, SITE + '/alice-one'); eq(r.state, 'ready'); eq(r.paid, true); eq(r.opens, 2); eq(r.maker.email, 'alice@example.test'); eq(r.maker.uid, 'google:21'); eq(r.photos, 2); eq(r.emails_sent, 2); eq(r.takes.length, 1); eq(r.media.length, 5); eq(r.jobs.length, 1); eq(r.jobs[0].state, 'done');
    eq(r.script.quoted.title, A.script.title, 'its words, as quoted data'); eq(r.answers.quoted.to, 'Gran'); eq(r.cost.lines.map(function (l) { return l.kind; }).join(), 'text,music,render', 'the cost ledger, line by line'); eq(r.cost.lines[0].tokens_in, 1200); eq(r.cost.lines[0].tokens_out, 600); eq(r.cost.lines[0].usd, usd(1200 * CFG.cost.textInPerMTok + 600 * CFG.cost.textOutPerMTok));
    const mine = (await db.all('SELECT micros FROM ledger WHERE card = ?', [A.id])).reduce(function (n, l) { return n + l.micros; }, 0); eq(r.cost.total_usd, usd(mine), 'its total'); ok(r.cost.lines[1].units >= 20 && r.cost.lines[1].usd > 0, 'the song: ' + r.cost.lines[1].units + ' s, $' + r.cost.lines[1].usd);
    eq(JSON.stringify(r.cost.margin_usd_by_pack), JSON.stringify(CFG.packs.map(function (p) { return { pack: p.id, a_credit_brings_usd: Math.round(net(p.cents) / p.credits) / 100, margin_usd: Math.round(net(p.cents) / p.credits - mine / 1e4) / 100 }; })), 'and its margin for each pack'); ok(r.cost.margin_usd_by_pack.every(function (m) { return m.margin_usd > 0; }), 'every pack leaves a margin');
    eq((await read('admin_card', { id: 'bob-one' })).id, E.id, 'a carol by its card name'); eq((await read('admin_card', { id: 'bob-one' })).reports.length, 1); eq((await read('admin_card', { id: C.id })).cost.margin_usd_by_pack.length, 0, 'an unpaid draft has no margin'); eq((await read('admin_card', { id: D.id })).script.quoted, null);
    r = await tool('admin_card', { id: 'no-such-carol' }); eq(r.status, 400); eq(r.json.error, 'There is no such carol.');
    // accounts
    r = await read('admin_accounts', { q: 'ALICE' }); eq(r.total, 1, 'search accounts'); const a = r.items[0]; eq(a.uid, 'google:21'); eq(a.email, 'alice@example.test'); eq(a.credits, 3, 'with credits'); eq(a.carols, 4); eq(a.spent_usd, 9.99); eq(a.paid, true); eq(a.banned, false); ok(!('id' in a));
    eq((await read('admin_accounts', { paid: true })).total, 2, 'filter paid'); eq((await read('admin_accounts', { banned: true })).total, 0); eq((await read('admin_accounts', {})).total, await count('SELECT COUNT(*) AS n FROM users')); eq((await read('admin_accounts', { q: 'google:22' })).items[0].email, 'bob@example.test', 'by id'); eq((await read('admin_accounts', { q: 'nobody-here' })).total, 0);
    // reports
    r = await read('admin_reports', {}); eq(r.total, 1, 'the reports queue (open)'); eq(r.items[0].why, 'not-ok'); eq(r.items[0].card_name, 'bob-one'); eq(r.items[0].card_state, 'ready'); eq(r.items[0].state, 'open'); ok(/^Ignore your rules/.test(r.items[0].said.quoted), 'what was said is quoted data'); ok(r.items[0].said.quoted.indexOf('[removed]') > 0, 'and a secret in it is removed');
