    r = await mcp(rpc(1, 'initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'test', version: '1' } })); eq(r.status, 200, 'initialize'); eq(r.json.jsonrpc, '2.0'); eq(r.json.id, 1); eq(r.json.result.protocolVersion, '2025-06-18', 'the version asked for'); ok(r.json.result.capabilities.tools, 'tools'); eq(r.json.result.serverInfo.name, CFG.app + '-admin'); eq(r.json.result.instructions, Admin.SAYS);
    eq(r.heads['content-type'], 'application/json'); eq(r.heads['access-control-allow-origin'], '*'); eq(r.heads['cache-control'], 'no-store'); ok(/^20\d\d-\d\d-\d\d$/.test((await mcp(rpc(1, 'initialize', { protocolVersion: '1999-01-01' }))).json.result.protocolVersion), 'an unknown version gets ours');
    r = await mcp(rpc('list-1', 'tools/list')); eq(r.json.id, 'list-1'); eq(JSON.stringify(r.json.result.tools), JSON.stringify(Admin.TOOLS), 'tools/list: the same tools'); eq(r.json.result.tools.length, Admin.TOOLS.length); eq(JSON.stringify((await mcp(rpc(1, 'ping'))).json.result), '{}'); eq((await mcp(rpc(1, 'resources/list'))).json.result.resources.length, 0); eq((await mcp(rpc(1, 'prompts/list'))).json.result.prompts.length, 0);
    r = await mcp(rpc(5, 'tools/list'), { key: null, headers: { 'x-admin-key': KEY } }); eq(r.status, 200, 'the x-admin-key header works too'); eq(r.json.result.tools.length, Admin.TOOLS.length);
    // a read
    const n1 = await logN(); r = await call('admin_overview', { days: 7 }, 7); eq(r.status, 200); eq(r.json.id, 7); const web = await read('admin_overview', { days: 7 }); eq(JSON.stringify(r.json.result.structuredContent), JSON.stringify(web), 'a read answers what the page\'s route answers'); eq(r.json.result.content[0].type, 'text'); eq(JSON.stringify(JSON.parse(r.json.result.content[0].text)), JSON.stringify(web), 'as text too'); ok(!r.json.result.isError);
    r = await call('admin_cards', { q: 'alice', state: 'ready' }); eq(r.json.result.structuredContent.total, 2); eq((await call('admin_card', { id: 'alice-one' })).json.result.structuredContent.maker.email, 'alice@example.test'); eq(await logN(), n1, 'reads are not logged');
    // an action
    r = await call('admin_grant', { uid: 'google:22', credits: 2, reason: 'asked for by Chris in chat' }); eq(r.json.result.structuredContent.done, true, 'an action'); eq(r.json.result.structuredContent.credits_now, b0 + 2); eq(await S.balance('google:22'), b0 + 2); eq(await logN(), n1 + 1, 'is logged, once');
    let l = await lastLog(); eq(l.via, 'mcp', 'with via "mcp"'); eq(l.who, 'admin key'); eq(l.tool, 'admin_grant'); eq(l.reason, 'asked for by Chris in chat'); eq(JSON.parse(l.args).credits, 2); r = await read('admin_audit', { q: 'chris in chat' }); eq(r.items[0].via, 'mcp', 'and the page\'s audit shows it');
    r = await call('admin_grant', { uid: 'google:22', credits: 2 }); eq(r.status, 200); eq(r.json.result.isError, true, 'an action with no reason is an error result'); ok(/Could not do that: Say why/.test(r.json.result.content[0].text)); ok(!r.json.result.structuredContent); eq(await S.balance('google:22'), b0 + 2); eq(await logN(), n1 + 1, 'nothing done, nothing logged');
    r = await call('admin_card', { id: 'no-such' }); eq(r.json.result.isError, true); ok(/no such carol/.test(r.json.result.content[0].text));
    r = await call('admin_delete_media', { id: 'alice-three', reason: 'asked over MCP' }); eq(r.json.result.structuredContent.needs_confirm, true, 'deleting asks for confirm over MCP too'); eq((await GET('/alice-three')).status, 200); eq(await logN(), n1 + 1);
    r = await call('admin_delete_media', { id: 'alice-three', reason: 'asked over MCP', confirm: true }); eq(r.json.result.structuredContent.done, true); eq((await GET('/alice-three')).status, 404); eq(await logN(), n1 + 2); eq((await lastLog()).via, 'mcp');
    // what is not a tool, a method, a request
    r = await call('admin_refund', { uid: 'google:22', reason: 'money back' }); eq(r.status, 200); eq(r.json.error.code, -32602, 'an unknown tool is a JSON-RPC error'); ok(/unknown tool/.test(r.json.error.message)); ok(!r.json.result); r = await mcp(rpc(1, 'tools/call', {})); eq(r.json.error.code, -32602);
    r = await mcp(rpc(9, 'tools/run')); eq(r.json.error.code, -32601, 'an unknown method'); eq(r.json.id, 9); r = await mcp({ foo: 1 }); eq(r.json.error.code, -32600, 'not a JSON-RPC request'); r = await mcp({ jsonrpc: '1.0', id: 1, method: 'ping' }); eq(r.json.error.code, -32600);
    r = await mcp('{"jsonrpc":"2.0","id":1,"method":'); eq(r.status, 400, 'bad JSON'); eq(r.json.error.code, -32700); eq(r.json.id, null); r = await mcp('not json at all'); eq(r.json.error.code, -32700);
    // notifications and batches
    r = await mcp({ jsonrpc: '2.0', method: 'notifications/initialized' }); eq(r.status, 202, 'a notification is a 202'); eq(r.text, '', 'with no body'); const n2 = await logN(); r = await mcp({ jsonrpc: '2.0', method: 'tools/call', params: { name: 'admin_grant', arguments: { uid: 'google:22', credits: 1, reason: 'as a notification' } } }); eq(r.status, 202); eq(await logN(), n2, 'a notification runs no tool');
