    eq(r.json[1].result.tools.length, Admin.TOOLS.length); eq(r.json[2].result.structuredContent.every_buy_says, CFG.finalSale); eq(r.json[3].error.code, -32601); r = await mcp([{ jsonrpc: '2.0', method: 'notifications/initialized' }, { jsonrpc: '2.0', method: 'notifications/cancelled' }]); eq(r.status, 202, 'a batch of notifications is a 202'); eq(r.text, '');
